final pool = MySQLConnectionPool(
  host: '127.0.0.1',
  port: 3306,
  userName: 'your_user',
  password: 'your_password',
  maxConnections: 10,
  databaseName: 'your_database_name',
  secure: true,
);
var result = await pool.execute("SELECT * FROM book WHERE id = :id", {"id": 1});
